// Recovered Dibbler tray presentation. Selecting stock never commits a transaction.
export function trayLayout(count,width,height){const n=Math.max(1,count),span=width*.72,slot=span/n;return Array.from({length:count},(_,i)=>({x:width*.14+i*slot,y:height*.38,w:slot,h:height*.29}));}
export function paintCounterTray(ctx,frame,entries,images,{width,height,selected,caption='',weaponPainter}={}){
 ctx.clearRect(0,0,width,height);ctx.drawImage(frame,0,0,width,height);const slots=trayLayout(entries.length,width,height);
 entries.forEach((entry,i)=>{const r=slots[i],im=images.get(entry.art),cx=r.x+r.w/2,cy=r.y+r.h*.55;if(entry.key===selected){ctx.save();ctx.strokeStyle='#b78e4d';ctx.lineWidth=Math.max(1,width/500);ctx.beginPath();ctx.ellipse(cx,cy+r.h*.22,r.w*.38,r.h*.30,0,0,Math.PI*2);ctx.stroke();ctx.restore();}
  if(im){const scale=Math.min(r.w*.90/im.width,r.h*.95/im.height);ctx.drawImage(im,cx-im.width*scale/2,cy-im.height*scale/2,im.width*scale,im.height*scale);}else if(entry.weapon&&weaponPainter){weaponPainter(ctx,entry.weapon,cx,cy+r.h*.23,Math.min(r.w/55,r.h/55));}else{ctx.save();ctx.fillStyle='#dfc79e';ctx.fillRect(r.x+r.w*.08,cy-r.h*.25,r.w*.84,r.h*.52);ctx.fillStyle='#493324';ctx.font=Math.max(10,width*.018)+'px Georgia';ctx.textAlign='center';ctx.fillText(entry.shortLabel||entry.label,cx,cy+r.h*.02,r.w*.78);ctx.restore();}
 });
 ctx.save();ctx.fillStyle='#3c291c';ctx.textAlign='center';ctx.textBaseline='middle';ctx.font='600 '+Math.max(13,Math.min(23,width*.031))+'px Georgia';ctx.fillText(caption,width*.5,height*.795,width*.76);ctx.restore();return slots;
}
export function mountCounterTray({root,onSelect,frameURL='assets/shop-tray/dibbler-tray.webp',weaponPainter}){
 const doc=root.ownerDocument,canvas=doc.createElement('canvas'),hits=doc.createElement('div'),labels=doc.createElement('div');root.className='services-counter-tray';canvas.setAttribute('role','img');hits.className='services-tray-hits';labels.className='services-tray-labels';const stage=doc.createElement('div');stage.className='services-tray-stage';stage.append(canvas,hits);root.append(stage,labels);let revision=0,model={entries:[],selected:'',caption:''};const cache=new Map();
 function image(url){if(!cache.has(url))cache.set(url,new Promise((yes,no)=>{const im=new Image();const timer=setTimeout(()=>{cache.delete(url);no(Error('Tray artwork timed out'));},20000);im.onload=()=>{clearTimeout(timer);yes(im);};im.onerror=()=>{clearTimeout(timer);cache.delete(url);no(Error('Tray artwork unavailable: '+url));};im.src=url;}));return cache.get(url);}
 async function draw(){const ticket=++revision,width=Math.max(300,Math.round(stage.clientWidth||640)),height=Math.round(width/2);canvas.width=width;canvas.height=height;const snapshot=model,images=new Map();let frame;try{frame=await image(frameURL);await Promise.all(snapshot.entries.filter(e=>e.art).map(async e=>{try{images.set(e.art,await image(e.art));}catch{}}));}catch{return;}if(ticket!==revision)return;const slots=paintCounterTray(canvas.getContext('2d'),frame,snapshot.entries,images,{width,height,selected:snapshot.selected,caption:snapshot.caption,weaponPainter});canvas.setAttribute('aria-label','Painted wooden shop tray. '+snapshot.entries.map(e=>e.label).join(', '));hits.replaceChildren();snapshot.entries.forEach((entry,i)=>{const label=entry.label+(entry.price===undefined?'':' · '+entry.price+' coin'+(entry.price===1?'':'s'));for(const visual of [true]){const button=doc.createElement('button');button.type='button';button.setAttribute('aria-pressed',String(entry.key===snapshot.selected));button.setAttribute('aria-label',label);button.title=label;button.onclick=()=>onSelect(entry);if(visual){const r=slots[i];button.className='services-tray-hit';button.setAttribute('aria-hidden','true');button.tabIndex=-1;button.style.cssText='left:'+r.x/width*100+'%;top:'+r.y/height*100+'%;width:'+r.w/width*100+'%;height:'+r.h/height*100+'%;';hits.append(button);}else{button.textContent=label;labels.append(button);}}});}
 const observer=new ResizeObserver(draw);observer.observe(stage);return {set(next){model=next;labels.replaceChildren();for(const entry of next.entries){const button=doc.createElement('button');button.type='button';button.textContent=entry.label+(entry.price===undefined?'':' · '+entry.price+' coin'+(entry.price===1?'':'s'));button.setAttribute('aria-pressed',String(entry.key===next.selected));button.onclick=()=>onSelect(entry);labels.append(button);}draw();},destroy(){revision++;observer.disconnect();root.replaceChildren();}};
}
